import random

def generate_tax_return(return_type, amount, tax_rate, deductions):
    # Ensure all fields are present and valid
    if not isinstance(return_type, str) or not isinstance(amount, float) or not isinstance(tax_rate, float) or not isinstance(deductions, list):
        raise ValueError("All fields must be strings, floats, or lists")

    # Generate realistic data
    return_data = {
        "return_type": return_type,
        "amount": amount,
        "tax_rate": tax_rate,
        "deductions": deductions
    }

    # Add constraints
    if not isinstance(deductions, list) or len(deductions) < 1:
        return_data["deductions"] = [deductions]

    # Ensure all deductions are valid
    for deduction in deductions:
        if not isinstance(deduction, str) or not isinstance(deduction, float) or not isinstance(deduction, list):
            return_data["deductions"].append(deduction)

    # Ensure all fields are present
    if not isinstance(return_data, dict) or not isinstance(return_data, list):
        return_data = dict(return_data)

